/* Reserve space for keyboard outlines inside scrollable modal content. */
.av-dialog-scroll,.av-sheet-scroll{padding:8px;margin:0}.av-overlay-layer>.av-dialog-content{padding:20px}.av-dialog-heading{padding:8px 8px 0}.av-dialog-description{margin:10px 8px 14px}.av-overlay-layer>.av-sheet-content{padding:20px}.av-overlay-layer>.av-drawer-content{padding:12px 16px max(20px,env(safe-area-inset-bottom));}.av-drawer-handle{margin-bottom:12px}
@media(max-width:480px){.av-overlay-layer>.av-dialog-content{padding:14px}.av-overlay-layer>.av-sheet-content{padding:16px 12px}.av-overlay-layer>.av-drawer-content{padding:12px 12px max(20px,env(safe-area-inset-bottom))}.av-sheet-header{padding-right:36px}}

/* Recharts measures within a zero-width wrapper; keep the measured pixel width. */
.av-chart .recharts-wrapper{max-width:none!important;flex-shrink:0}.av-chart .recharts-surface{max-width:none!important}
.av-badge{align-self:flex-start;width:fit-content;max-width:100%;flex:0 0 auto}

/* Clip scrolling content, not the optical shell's contact and ambient shadows. */
.av-overlay-layer>.av-dialog-content,.av-overlay-layer>.av-sheet-content{overflow:visible}
